formula:
IFERROR(__xludf.DUMMYFUNCTION("ARRAYFORMULA({
  IFERROR(VLOOKUP(
    INDEX(QUERY(O2:O1054, ""select O, count(O) where O != 1 and O is not null group by O order by count(O) desc""), ,1),
    $R$2:$S$9,
    2,
    FALSE
  ), """"),
  INDEX(QUERY(O2:O1054, ""select O, count(O) where O != "&"1 and O is not null group by O order by count(O) desc""), ,2)
})"),"")
